document.addEventListener('DOMContentLoaded', () => { document.querySelectorAll('a[href^="#"]').forEach(anchor => { anchor.addEventListener('click', function (e) { const targetId = this.getAttribute('href'); if (targetId === '#' || targetId === '') return; const target = document.querySelector(targetId); if (target) { e.preventDefault(); const duration = 1000; const targetPosition = target.getBoundingClientRect().top + window.pageYOffset; const startPosition = window.pageYOffset; const distance = targetPosition - startPosition; let startTime = null; function animation(currentTime) { if (startTime === null) startTime = currentTime; const timeElapsed = currentTime - startTime; const run = easeInOutQuad(timeElapsed, startPosition, distance, duration); window.scrollTo(0, run); if (timeElapsed < duration) requestAnimationFrame(animation); } function easeInOutQuad(t, b, c, d) { t /= d / 2; if (t < 1) return c / 2 * t * t + b; t--; return -c / 2 * (t * (t - 2) - 1) + b; } requestAnimationFrame(animation); } }); }); const themeToggleBtn = document.getElementById('theme-toggle'); const themeToggleBtnMobile = document.getElementById('theme-toggle-mobile'); const themeToggleIcon = document.getElementById('theme-toggle-icon'); const themeToggleIconMobile = document.getElementById('theme-toggle-icon-mobile'); const activeTheme = localStorage.getItem('theme') || 'light'; if (activeTheme === 'dark') { document.documentElement.classList.add('dark'); if (themeToggleIcon) themeToggleIcon.textContent = 'light_mode'; if (themeToggleIconMobile) themeToggleIconMobile.textContent = 'light_mode'; } else { document.documentElement.classList.remove('dark'); if (themeToggleIcon) themeToggleIcon.textContent = 'dark_mode'; if (themeToggleIconMobile) themeToggleIconMobile.textContent = 'dark_mode'; } function toggleTheme() { const isDark = document.documentElement.classList.contains('dark'); if (isDark) { document.documentElement.classList.remove('dark'); localStorage.setItem('theme', 'light'); if (themeToggleIcon) themeToggleIcon.textContent = 'dark_mode'; if (themeToggleIconMobile) themeToggleIconMobile.textContent = 'dark_mode'; } else { document.documentElement.classList.add('dark'); localStorage.setItem('theme', 'dark'); if (themeToggleIcon) themeToggleIcon.textContent = 'light_mode'; if (themeToggleIconMobile) themeToggleIconMobile.textContent = 'light_mode'; } } if (themeToggleBtn) { themeToggleBtn.addEventListener('click', toggleTheme); } if (themeToggleBtnMobile) { themeToggleBtnMobile.addEventListener('click', toggleTheme); } const mobileMenuBtn = document.getElementById('mobile-menu-btn'); const mobileMenuOverlay = document.getElementById('mobile-menu-overlay'); const mobileMenuCloseBtn = document.getElementById('mobile-menu-close'); const mobileMenuLinks = document.querySelectorAll('#mobile-menu-overlay a'); function toggleMenu() { const isClosed = mobileMenuOverlay.classList.contains('translate-x-full'); if (isClosed) { mobileMenuOverlay.classList.remove('translate-x-full'); document.body.classList.add('overflow-hidden'); } else { mobileMenuOverlay.classList.add('translate-x-full'); document.body.classList.remove('overflow-hidden'); } } if (mobileMenuBtn) { mobileMenuBtn.addEventListener('click', toggleMenu); } if (mobileMenuCloseBtn) { mobileMenuCloseBtn.addEventListener('click', toggleMenu); } mobileMenuLinks.forEach(link => { link.addEventListener('click', toggleMenu); }); });